<script setup lang="ts">
import { computed } from 'vue'
import type { ElderApp } from '../composables/useElderApp'
import AppIcon from '../components/AppIcon.vue'
const props = defineProps<{ app: ElderApp }>()
const status = computed(() => props.app.state.sos && props.app.state.data ? props.app.state.data.sos.states[props.app.state.sos] : null)
</script>
<template><div class="content"><template v-if="status"><p class="demo-note"><b>模拟求助 · 未实际通知任何人</b><br>手动演示的状态不代表真实送达。</p><section class="card sos-state"><span class="avatar"><AppIcon name="sos"/></span><h1>{{ status.title }}<small>模拟</small></h1><p>{{ status.description }}</p></section><section class="card"><h2>通知对象</h2><p v-for="recipient in app.state.data?.sos.recipients" :key="recipient">{{ recipient }}</p><p v-if="app.state.sos === 'cancelled' && app.state.reached">已模拟向收到求助的对象同步取消。</p></section><div class="actions"><template v-if="app.state.sos === 'failed'"><button class="primary" data-testid="retry-help" @click="app.progress('sending')">重新发送（模拟）</button><button class="secondary" @click="app.state.feedback = '未配置真实联系人电话，无法拨号。请使用手机电话功能联系。'">拨打电话 · 暂未配置</button></template><button v-if="app.state.sos !== 'cancelled'" class="secondary" data-testid="cancel-help" @click="app.state.modal = 'cancel'">误触了，取消求助</button><button v-else class="primary" data-testid="help-records" @click="app.go('requests')">查看处理记录</button></div><section v-if="app.state.sos === 'sending' || app.state.sos === 'delivered'" class="card demo-controls"><h2>演示控件 · 非正式功能</h2><p>手动切换进度，查看不同界面。</p><div class="actions"><template v-if="app.state.sos === 'sending'"><button data-testid="deliver-help" @click="app.progress('delivered')">模拟送达</button><button data-testid="fail-help" @click="app.progress('failed')">模拟发送失败</button></template><button v-else data-testid="respond-help" @click="app.progress('responded')">模拟有人响应</button></div></section></template><p v-else class="empty">求助服务尚未接入</p></div></template>
